mapper.select:
select

,
ifnull(c11.C_Name, pro.P_Use_Unit) as pUseUnitName
from Project_Cp mn

left join SYS_Company c11 on c11.C_Id=pro.P_Use_Unit

    ${params.authSql}


    where 1=1



    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Cp_Create_Time desc

select dta.*,(dta.cpDtlCount-dta.completeCount) as unfinishedCount from ( select us.*, ( select count(distinct cp1.Cp_Id) from Project_Cp cp1 left join Project_Cp_Dtl pcd on cp1.Cp_Id=pcd.Cp_Id where pcd.Cpd_Person_Id=us.uId or pcd.Cpd_Create_Uid=us.uId) as userCpCount, (select count(1) from Project_Cp_Dtl cpDtl1 where cpDtl1.Cpd_Person_Id=us.uId and cpDtl1.Cpd_Status=1) as cpDtlCount, (select count(1) from Project_Cp_Dtl cpDtl2 where cpDtl2.Cpd_Person_Id=us.uId and cpDtl2.Cpd_Status=1 and cpDtl2.Cpd_State=7) as completeCount, (select count(1) from Project_Cp_Dtl cpDtl4 where cpDtl4.Cpd_Person_Id=us.uId and cpDtl4.Cpd_Status=1 and ((cpDtl4.Cpd_End_Time is null and cpDtl4.Cpd_Plan_End_Time<now()) or (cpDtl4.Cpd_End_Time is not null and cpDtl4.Cpd_Plan_End_Time <= cpDtl4.Cpd_End_Time) )) as overTimeCount from ( select cpDtl.Cpd_Person_Id as uId,cpDtl.Cpd_Person_Name as uName from Project_Cp_Dtl cpDtl where cpDtl.Cpd_Status=1 and cpDtl.Cpd_Person_Id is not null union select cpDtl1.Cpd_Create_Uid as uId,cpDtl1.Cpd_Create_Uname as uName from Project_Cp_Dtl cpDtl1 where cpDtl1.Cpd_Status=1 and cpDtl1.Cpd_Create_Uid is not null ) us ) dta
uName like concat('%',#{params.uName},'%')
order by ${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

SELECT IFNULL(ps.alreadyOver, 0) as alreadyOver, IFNULL(ps.underApproval, 0) as underApproval, IFNULL(ts.milestoneCount, 0) as milestoneCount, IFNULL(ts.firstLevelCount, 0) as firstLevelCount, IFNULL(ts.secondLevelCount, 0) as secondLevelCount FROM ( SELECT SUM(CASE WHEN lp.state = 7 THEN 1 ELSE 0 END) AS alreadyOver, SUM(CASE WHEN lp.state NOT IN (0,3,7) THEN 1 ELSE 0 END) AS underApproval FROM ( SELECT p1.* FROM project_cp_rpr p1 LEFT JOIN project_cp_rpr p2 ON p2.Cpd_Id = p1.Cpd_Id AND ( p2.create_time > p1.create_time OR (p2.create_time = p1.create_time AND p2.id > p1.id) ) WHERE p2.Cpd_Id IS NULL ) lp JOIN Project_Cp pc ON pc.Cp_Id = lp.Cp_Id AND pc.State = 7 JOIN pre_project pro ON pro.P_Id = pc.P_Id WHERE EXISTS ( SELECT 1 FROM Project_Cp_Dtl pcd JOIN Gantt_Tasks gt ON gt.Cpl_Id = pcd.Cpd_Cpl_Id JOIN Gantt_Plan gp ON gp.Plan_Id = gt.Plan_Id WHERE pcd.Cpd_Id = lp.Cpd_Id AND gp.P_Id = pc.P_Id AND gt.Task_Type = '01' )
) ps, ( SELECT SUM(CASE WHEN pcd.task_importance = '99' THEN 1 ELSE 0 END) AS milestoneCount, SUM(CASE WHEN pcd.task_importance = '01' THEN 1 ELSE 0 END) AS firstLevelCount, SUM(CASE WHEN pcd.task_importance = '02' THEN 1 ELSE 0 END) AS secondLevelCount FROM Project_Cp_Dtl pcd JOIN Project_Cp pc ON pc.Cp_Id = pcd.Cp_Id AND pc.State = 7 JOIN pre_project pro ON pro.P_Id = pc.P_Id WHERE EXISTS ( SELECT 1 FROM Gantt_Tasks gt JOIN Gantt_Plan gp ON gp.Plan_Id = gt.Plan_Id WHERE gt.Cpl_Id = pcd.Cpd_Cpl_Id AND gp.P_Id = pc.P_Id AND gt.Task_Type = '01' )
) ts
